<?php
function manual_adjustment_create($input){
 adjustment_access();$raw=$input['products']??[];if(!is_array($raw)||!$raw||count($raw)>100)throw new Exception('Select between 1 and 100 products.');$ids=[];foreach($raw as $x){$p=active_product(is_array($x)?($x['product_id']??0):0);if(isset($ids[$p['id']]))throw new Exception('Duplicate product. Use one count line per product.');$ids[$p['id']]=(int)$p['id'];}
 return process_transaction(function()use($input,$ids){$id=adjustment_create(['count_date'=>$input['count_date']??'','product_ids'=>array_values($ids),'entry_method'=>'Manual']);adjustment_event($id,'Manual session created',['products'=>array_values($ids),'stock_changed'=>false]);return $id;});
}
function manual_adjustment_save($id,$input){
 adjustment_access();return process_transaction(function()use($id,$input){$b=adjustment_check_open($id,true);if((string)$b['revision']!==(string)($input['revision']??''))throw new Exception('Count revision changed. Reopen this count.');if($b['status']==='Awaiting Approval')throw new Exception('Return this count for review before editing.');$stage=$input['stage']??'';if(!in_array($stage,['First','Recount'],true))throw new Exception('Invalid count stage.');if($stage==='Recount'&&!in_array($b['status'],['Recount Required','Recounted','Error'],true))throw new Exception('Save the first count before recounting.');
 $values=$input['counts']??[];if(!is_array($values))throw new Exception('Invalid count entries.');$lines=count_lines($id);$known=array_column($lines,'id');foreach(array_keys($values) as $key)if(!in_array((int)$key,array_map('intval',$known),true))throw new Exception('Count line does not belong to this session.');
 $rows=[['Physical Inventory Count'],['Batch',$b['batch_ref']],['Revision',(string)$b['revision']],['Stage',$stage],['Cutoff',$b['cutoff_at']],['Master SKU','Product Description','On Hand','Actual Good','Actual Packaging','Actual Damaged','Actual Other Restricted','Remarks']];
 foreach($lines as $l){$v=$values[$l['id']]??[];if(!is_array($v))throw new Exception('Invalid count line.');$rows[]=[$l['master_sku'],$l['product_name'],(string)$l['on_hand'],$v['good']??'',$v['packaging']??'',$v['damaged']??'',$v['other']??'',$v['remarks']??''];}
 $hash=hash('sha256',json_encode(['Manual',$rows]));$errors=adjustment_upload($id,$rows,'Manual '.$stage.' count',$hash,null);adjustment_event($id,'Manual count entry',['stage'=>$stage,'errors'=>$errors,'stock_changed'=>false]);return $errors;});
}
function manual_adjustment_create_form(){
 echo '<div class="card"><h3>Manual Inventory Adjustment</h3><p>Select the products to count. The system captures their current on-hand balances; enter the actual counts on the next screen. Stock changes only after separate approval.</p>';adjustment_form_start('manual_create',0);echo '<label>Count Date<input type="date" name="count_date" value="'.date('Y-m-d').'" min="'.date('Y-m-d').'" max="'.date('Y-m-d').'" required></label><div data-manual-products><div data-product-lines><div class="card stack" data-product-line><label>Product / Master SKU</label>'.picker('products[0][product_id]','Search product or SKU...',true,'',false).'<button type="button" class="btn ghost sm" data-remove-line>Remove Item</button></div></div><button type="button" class="btn ghost" data-add-product>+ Add Item Line</button></div><button class="btn primary">Create Snapshot & Enter Actual Counts</button></form></div>';
}
function manual_adjustment_entry_forms($b,$lines){
 if(!can_action('upload_inventory_count')||in_array($b['status'],['Applied','Cancelled','Reversed','Awaiting Approval'],true))return;
 echo '<div class="card"><h3>Manual Count Entry</h3><p>Enter all four stock conditions; use 0 for none. Actual total and variance are calculated automatically. A blank row means not counted. Save First Count, then enter a physical Recount before review.</p>';
 foreach(['First'=>'First Count','Recount'=>'Recount'] as $stage=>$label){if($stage==='Recount'&&!in_array($b['status'],['Recount Required','Recounted','Error'],true))continue;echo '<details '.($stage==='First'&&$b['status']==='Exported'?'open':'').'><summary class="btn secondary">'.$label.'</summary>';adjustment_form_start('manual_save',$b['id']);echo '<input type="hidden" name="revision" value="'.$b['revision'].'"><input type="hidden" name="stage" value="'.$stage.'"><div class="table-wrap"><table class="table"><tr><th>Product / SKU</th><th>System On Hand</th><th>Sellable</th><th>For Packaging</th><th>Damaged / Leak</th><th>Other Restricted</th><th>Actual Total</th><th>Variance</th><th>Remarks</th></tr>';
 foreach($lines as $l){if($stage==='Recount'&&$l['actual_count']===null)continue;$saved=$stage==='First'?(json_decode($l['remarks']??'null',true)?:[]):(json_decode($l['recount_json']??'null',true)?:[]);$v=$stage==='First'?($saved['first']??[]):($saved['counts']??[]);echo '<tr data-manual-count-row data-on-hand="'.(int)$l['on_hand'].'"><td>'.e($l['master_sku']).'<br>'.e($l['product_name']).'</td><td>'.(int)$l['on_hand'].'</td>';foreach(['good','packaging','damaged','other'] as $k)echo '<td><input aria-label="'.e($l['master_sku'].' '.$k.' '.$label).'" style="min-width:90px" type="number" min="0" max="99999999" step="1" name="counts['.$l['id'].']['.$k.']" value="'.e($v[$k]??'').'"></td>';echo '<td data-actual-total>—</td><td data-variance>—</td><td><input aria-label="'.e($l['master_sku'].' remarks '.$label).'" name="counts['.$l['id'].'][remarks]" value="'.e($stage==='First'?($saved['first_remarks']??''):($saved['remarks']??'')).'" placeholder="Required for discrepancy"></td></tr>';}
 echo '</table></div><button class="btn primary">Validate & Save '.$label.'</button></form></details>';}
 echo '</div>';
}
